interface KanbanCard {
  row: WBSRow;
  status: KanbanStatus;
}

interface KanbanColumn {
  status: KanbanStatus;
  label: string;
  icon: React.ReactNode;
  color: string;
  bgColor: string;
  dropProgress: number;
}

